import sys
R, C = int(sys.argv[1]), int(sys.argv[2])
panes = []
for line in sys.stdin:
    f = line.split()
    if not f: continue
    panes.append(tuple(int(x) for x in f[1:5]))
grid = {}
bad = []
for i, (r, c, rows, cols) in enumerate(panes):
    if rows <= 0 or cols <= 0 or r < 0 or c < 0 or r + rows > R or c + cols > C:
        bad.append('bounds')
    for y in range(r, r + rows):
        for x in range(c, c + cols):
            if (y, x) in grid: bad.append('overlap')
            grid[(y, x)] = i
def free(y, x): return 0 <= y < R and 0 <= x < C and (y, x) not in grid
for y in range(R):
    for x in range(C):
        if (y, x) in grid: continue
        touch = any(n in grid for n in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)))
        wide = any(free(y+a, x+b) and free(y+a, x) and free(y, x+b) for a in (-1, 1) for b in (-1, 1))
        if not touch or wide: bad.append('hole:%d,%d' % (y, x))
print('panes=%d bounds-overlap-holes=%s' % (len(panes), 'ok' if not bad else ','.join(sorted(set(bad))[:3])))

