echo "after-creator-exit: list=[$(screen list)] state-rc=$(screen state live >/dev/null 2>&1; echo $?) child-alive=$([[ -d /proc/$child ]] && echo yes || echo no)"
screen send-keys live fork >/dev/null 2>&1; await "$P/L1.grand"; grand=$(<"$P/L1.grand")
echo "resistant-descendant-started=$([[ $grand =~ ^[0-9]+$ && -d /proc/$grand ]] && echo yes || echo no)"
files_before=$(find "$S/live" -type f -name pid | wc -l); socks_before=$(find "$S/live" -name '*.sock' | wc -l)
echo "before-kill: pid-files>=2=$([[ $files_before -ge 2 ]] && echo yes || echo no) sockets>=1=$([[ $socks_before -ge 1 ]] && echo yes || echo no)"
