st() { if [[ ! -d /proc/$1 ]]; then echo absent; else read -r l < /proc/$1/stat; r=${l##*) }; [[ ${r%% *} == Z ]] && echo zombie || echo live; fi; }
echo "after-kill: child=$(st $child) descendant=$(st $grand) broker=$(st $broker)"
echo "after-kill: session-dir-removed=$([[ ! -e $S/live ]] && echo yes || echo no) pid-files=$(find "$S" -name pid 2>/dev/null | wc -l) sockets=$(find "$S" -name '*.sock' 2>/dev/null | wc -l) state-rc-nonzero=$(screen state live >/dev/null 2>&1; [[ $? != 0 ]] && echo yes || echo no) list=[$(screen list)]"
for ((i=0;i<250;i++)); do [[ $(snap_procs) == "$BASE" ]] && break; nap 0.02; done
echo "end: live-extra-processes=$([[ $(snap_procs) == "$BASE" ]] && echo 0 || echo some)"; extras "$BASE"
z=0; for c in /proc/[0-9]*; do read -r l < $c/stat 2>/dev/null || continue; r=${l##*) }; [[ ${r%% *} == Z ]] && z=$((z+1)); done; echo "end: zombies=$z"

